60	// Fetch runs git fetch with checkpoint token injection and optional
61	// filtered fetches (--filter=blob:none when settings enable it).
62	// GIT_TERMINAL_PROMPT=0 is always set.
63	//
64	// Callers that pass a remote name (e.g., "origin") and want filtered fetches to
65	// resolve the name to a URL (to avoid persisting promisor settings) should call
66	// ResolveFetchTarget first and pass the resolved target as opts.Remote.
67	func Fetch(ctx context.Context, opts FetchOptions) ([]byte, error) {
68		args := []string{"fetch", "--no-auto-gc"}
69		if opts.NoTags {
70			args = append(args, "--no-tags")
71		}
72		args = append(args, opts.ExtraArgs...)
73		switch {
74		case opts.Shallow:
75			args = append(args, "--depth=1")
76		case opts.Depth > 0:
77			args = append(args, fmt.Sprintf("--depth=%d", opts.Depth))
78		case opts.Unshallow && isShallowRepository(ctx, opts.Dir):
79			args = append(args, "--unshallow")
80		}
81		filtered := !opts.NoFilter && settings.IsFilteredFetchesEnabled(ctx)
82		if filtered {
83			args = append(args, "--filter=blob:none")
84		}
85		args = append(args, opts.Remote)
86		args = append(args, opts.RefSpecs...)
87	
88		cmd := newCommand(ctx, args...)
89		if opts.Dir != "" {
90			cmd.Dir = opts.Dir
91		}
92		disableTerminalPrompt(cmd)
93		out, err := cmd.CombinedOutput()
94		if err != nil {
95			return out, fmt.Errorf("git fetch: %w", err)
96		}
97		if filtered && IsURL(opts.Remote) {
98			// Stamp the URL git actually fetched from: with a checkpoint token set,
99			// newCommand rewrites SSH targets to HTTPS, and git records the
100			// promisor entry under the rewritten URL.
101			target := opts.Remote
102			if token := strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar)); token != "" && isValidToken(token) {
103				target, _ = resolveTargetForTokenAuth(ctx, target)
104			}
105			markPromisorEntrySkipped(ctx, opts.Dir, target)
106		}
107		return out, nil
108	}
