205	// Push runs git push --no-verify --porcelain with token injection.
206	// GIT_TERMINAL_PROMPT=0 is always set.
207	func Push(ctx context.Context, remote, refSpec string) (PushResult, error) {
208		return PushWithOptions(ctx, PushOptions{
209			Remote:   remote,
210			RefSpecs: []string{refSpec},
211		})
212	}
