214	// PushWithOptions runs git push --no-verify --porcelain with token injection.
215	// GIT_TERMINAL_PROMPT=0 is always set.
216	func PushWithOptions(ctx context.Context, opts PushOptions) (PushResult, error) {
217		pushTarget, err := resolvePushCommandTarget(ctx, opts.Remote)
218		if err != nil {
219			return PushResult{}, fmt.Errorf("resolve push target: %w", err)
220		}
221	
222		args := []string{"push", "--no-verify", "--porcelain"}
223		args = append(args, opts.ExtraArgs...)
224		args = append(args, pushTarget)
225		args = append(args, opts.RefSpecs...)
226	
227		cmd := newCommand(ctx, args...)
228		if opts.Dir != "" {
229			cmd.Dir = opts.Dir
230		}
231		disableTerminalPrompt(cmd)
232		output, err := cmd.CombinedOutput()
233		if err != nil {
234			return PushResult{Output: string(output)}, fmt.Errorf("git push: %w", err)
235		}
236		return PushResult{Output: string(output)}, nil
237	}
