389	// replaceFirstPositional returns a copy of args with the first non-flag
390	// argument after args[0] (the git subcommand) replaced by newTarget. Callers
391	// use this to rewrite a remote name/URL after resolution without mutating the
392	// original slice.
393	func replaceFirstPositional(args []string, newTarget string) []string {
394		out := make([]string, len(args))
395		copy(out, args)
396		for i := 1; i < len(out); i++ {
397			if !strings.HasPrefix(out[i], "-") {
398				out[i] = newTarget
399				return out
400			}
401		}
402		return out
403	}
404	
405	// extractRemoteFromArgs finds the remote URL or name from git command args.
406	// It skips the subcommand (first arg) and any flags (args starting with "-"),
407	// returning the first positional argument, which is the remote for push/fetch/ls-remote.
408	func extractRemoteFromArgs(args []string) string {
409		if len(args) < 2 {
410			return ""
411		}
412		// Skip subcommand (e.g., "push", "fetch", "ls-remote").
413		for _, arg := range args[1:] {
414			if !strings.HasPrefix(arg, "-") {
415				return arg
416			}
417		}
418		return ""
419	}
420	
421	// appendCheckpointTokenEnv appends GIT_CONFIG_COUNT-based env vars to inject
422	// an Authorization header into git HTTP requests. The token is sent as a Basic
423	// credential with the format "x-access-token:<token>" (base64-encoded), which
424	// is compatible with GitHub's token authentication.
425	//
426	// Existing GIT_CONFIG_KEY_*/GIT_CONFIG_VALUE_* entries are preserved; the new
427	// http.extraHeader entry is appended at the next free index and
428	// GIT_CONFIG_COUNT is updated accordingly. This keeps caller-injected git
429	// config (e.g., safe.directory, custom CA settings) intact.
430	func appendCheckpointTokenEnv(baseEnv []string, token string) []string {
431		existingCount := 0
432		for _, e := range baseEnv {
433			rest, ok := strings.CutPrefix(e, "GIT_CONFIG_COUNT=")
434			if !ok {
435				continue
436			}
437			if n, err := strconv.Atoi(rest); err == nil && n > 0 {
438				existingCount = n
439			}
440		}
441	
442		// Strip the old GIT_CONFIG_COUNT entry (we'll emit a new one) but keep
443		// GIT_CONFIG_KEY_*/GIT_CONFIG_VALUE_* entries in place.
444		filtered := make([]string, 0, len(baseEnv)+3)
445		for _, e := range baseEnv {
446			if strings.HasPrefix(e, "GIT_CONFIG_COUNT=") {
447				continue
448			}
449			filtered = append(filtered, e)
450		}
451	
452		idx := existingCount
453		encoded := base64.StdEncoding.EncodeToString([]byte("x-access-token:" + token))
454		return append(filtered,
455			fmt.Sprintf("GIT_CONFIG_COUNT=%d", existingCount+1),
456			fmt.Sprintf("GIT_CONFIG_KEY_%d=http.extraHeader", idx),
457			fmt.Sprintf("GIT_CONFIG_VALUE_%d=Authorization: Basic %s", idx, encoded),
458		)
459	}
460	
461	// isValidToken returns false if the token contains control characters (bytes < 0x20
462	// or 0x7F). This prevents HTTP header injection via CR/LF or other control chars
463	// embedded in the token value.
464	func isValidToken(token string) bool {
465		for _, b := range []byte(token) {
466			if b < 0x20 || b == 0x7F {
467				return false
468			}
469		}
470		return true
471	}
472	
473	// resolvePushCommandTarget returns the target to pass to git push. When a
474	// dedicated checkpoint_remote is configured, the checkpoint URL is returned so
475	// the push is routed to the separate checkpoint repo. Otherwise the remote
476	// name is returned unchanged so git uses its own config, updates the
477	// refs/remotes/<name>/<branch> tracking ref, and subsequent calls can use that
478	// tracking ref to skip redundant pushes.
479	//
480	// SSH→HTTPS coercion for token auth is handled by newCommand, which rewrites
481	// the command args or injects per-host config, rather than being baked into
482	// the target here.
483	func resolvePushCommandTarget(ctx context.Context, target string) (string, error) {
484		if target == "" || IsURL(target) || isLocalPath(target) {
485			return target, nil
486		}
487	
488		pushTarget, enabled, err := PushURL(ctx, target)
489		if err != nil {
490			return "", err
491		}
492		if !enabled || pushTarget == "" {
493			return target, nil
494		}
495		return pushTarget, nil
496	}
497	
498	func isLocalPath(target string) bool {
499		return filepath.IsAbs(target) || strings.HasPrefix(target, "./") || strings.HasPrefix(target, "../")
500	}
501	
502	// disableTerminalPrompt sets GIT_TERMINAL_PROMPT=0 on the command,
503	// initializing cmd.Env from os.Environ() if nil.
504	func disableTerminalPrompt(cmd *exec.Cmd) {
505		if cmd.Env == nil {
506			cmd.Env = os.Environ()
507		}
508		cmd.Env = append(cmd.Env, "GIT_TERMINAL_PROMPT=0")
509	}
